 static void bad(SignedSeedFrame f,ContextSignedWitnessPlanAudit.Receipt p,Snapshot x,List<Snapshot> foreign,String why){ContextSignedWitnessFrameAudit.Inspection r=ContextSignedWitnessFrameAudit.inspect(f,p,x,foreign,64,8,WORK,WORK);require(!r.audited&&r.output==null,why+": no audit receipt");}
