  SignedSeedResult low=ContextWitnessResultTransport.signedWitnessFrame(p,x,foreign,64,8,1,WORK);require(!low.assembled&&low.output==null,"adapter work exhaustion exposes no partial common/private frame");SignedSeedResult unaudited=ContextWitnessResultTransport.signedWitnessFrame(p,x,foreign,64,8,WORK,1);require(!unaudited.assembled&&unaudited.output==null,"fresh plan audit budget required");SignedSeedResult rank=ContextWitnessResultTransport.signedWitnessFrame(p,x,foreign,64,1,WORK,WORK);require(!rank.assembled&&rank.output==null&&rank.phase.equals("private"),"local common+private rank bound checked atomically");ContextSignedWitnessFrameAudit.Inspection limited=ContextSignedWitnessFrameAudit.inspect(f,p,x,foreign,64,8,1,WORK);require(!limited.audited&&limited.output==null,"direct frame audit exhaustion has no receipt");reject(()->ContextSignedWitnessFrameAudit.check(receipt,p,x,foreign,64,8,1,WORK),"fresh frame replay cannot reuse historical work");reject(()->ContextSignedWitnessFrameAudit.check(receipt,p,x,foreign,64,7,WORK,WORK),"frame policy expectation is exact");
